import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { createShutdownHooks } from './shutdown.js';

function harness(hasActive: boolean) {
  const events: string[] = [];
  let releaseStop: () => void = () => undefined;
  const stopGate = new Promise<void>((resolve) => {
    releaseStop = resolve;
  });
  const hooks = createShutdownHooks({
    stop: async () => {
      events.push('stop');
      await stopGate;
    },
    hasActive: () => hasActive,
    quit: () => {
      events.push('quit');
    },
  });
  return { hooks, events, releaseStop };
}

describe('shutdown hooks', () => {
  it('routes window close and consent revocation through the stop path', () => {
    const test = harness(true);
    test.hooks.beginStart();
    assert.equal(test.hooks.captureAllowed(), true);
    test.hooks.onWindowAllClosed();
    assert.equal(test.hooks.captureAllowed(), false);
    test.hooks.onConsentRevoked();
    assert.equal(test.hooks.captureAllowed(), false);
    test.hooks.beginStart();
    assert.equal(test.hooks.captureAllowed(), true);
    assert.deepEqual(test.events, ['stop', 'stop']);
  });

  it('prevents quit while active, stops first, and quits afterward', async () => {
    const test = harness(true);
    let prevented = 0;
    test.hooks.onBeforeQuit({ preventDefault: () => { prevented += 1; } });

    assert.equal(prevented, 1);
    assert.deepEqual(test.events, ['stop']);
    test.releaseStop();
    for (let turn = 0; turn < 20 && !test.events.includes('quit'); turn += 1) {
      await new Promise((resolve) => setImmediate(resolve));
    }
    assert.deepEqual(test.events, ['stop', 'quit']);
  });

  it('blocks repeated quit requests until the pending shutdown settles', async () => {
    const test = harness(true);
    let prevented = 0;
    test.hooks.onBeforeQuit({ preventDefault: () => { prevented += 1; } });
    test.hooks.onBeforeQuit({ preventDefault: () => { prevented += 1; } });

    assert.equal(prevented, 2);
    assert.deepEqual(test.events, ['stop']);
    test.releaseStop();
    for (let turn = 0; turn < 20 && !test.events.includes('quit'); turn += 1) {
      await new Promise((resolve) => setImmediate(resolve));
    }
    assert.deepEqual(test.events, ['stop', 'quit']);
  });

  it('keeps the app alive and retries when stop rejects', async () => {
    let attempts = 0;
    const events: string[] = [];
    const hooks = createShutdownHooks({
      stop: async () => {
        attempts += 1;
        events.push('stop');
        if (attempts === 1) throw new Error('teardown failed');
      },
      hasActive: () => true,
      quit: () => {
        events.push('quit');
      },
    });
    let prevented = 0;
    hooks.onBeforeQuit({ preventDefault: () => { prevented += 1; } });
    await new Promise((resolve) => setImmediate(resolve));
    assert.deepEqual(events, ['stop']);
    assert.equal(prevented, 1);

    hooks.onBeforeQuit({ preventDefault: () => { prevented += 1; } });
    await new Promise((resolve) => setImmediate(resolve));
    assert.deepEqual(events, ['stop', 'stop', 'quit']);
    assert.equal(prevented, 2);
  });

  it('does not block a quit when no session or stop is active', () => {
    const test = harness(false);
    let prevented = 0;
    test.hooks.onBeforeQuit({ preventDefault: () => { prevented += 1; } });
    assert.equal(prevented, 0);
    assert.deepEqual(test.events, []);
  });
});

// Why: both temp files must be durable before either artifact is replaced.
// Removed: independent saves could start a report replacement before the new PGN temp file existed.
export async function saveReportArtifacts(
  root: string,
  sessionId: string,
  text: string,
  pgns: readonly string[],
  fs: AtomicFileSystem = defaultAtomicFileSystem,
): Promise<void> {
  const parsed = reportBuildRequestSchema.safeParse({ sessionId, pgns });
  if (!parsed.success) throw new Error('The PGN batch is not valid.');
  await exclusive(root, async () => {
    const dir = sessionDir(root, sessionId);
    await stat(path.join(dir, 'meta.json'));
    const gamesFile = path.join(dir, 'games.json');
    const reportFile = path.join(dir, 'report.json');
    const pending = new Set<string>();
    let previousGames: string | null = null;
    try {
      previousGames = await readFile(gamesFile, 'utf8');
    } catch (error) {
      if (!isEnoent(error)) throw error;
    }
    let gamesCommitted = false;
    try {
      const gamesTmp = await stageAtomic(gamesFile, jsonText(parsed.data.pgns), fs);
      pending.add(gamesTmp);
      const reportTmp = await stageAtomic(reportFile, text, fs);
      pending.add(reportTmp);
      await commitAtomic(gamesTmp, gamesFile, fs);
      pending.delete(gamesTmp);
      gamesCommitted = true;
      await commitAtomic(reportTmp, reportFile, fs);
      pending.delete(reportTmp);
    } catch (error) {
      await Promise.all([...pending].map((tmp) => removeAtomicTemp(tmp, fs)));
      // A failed report commit must not leave the new PGNs beside the old report.
      if (gamesCommitted) {
        try {
          if (previousGames === null) {
            await fs.rm(gamesFile, { force: true });
          } else {
            const restore = await stageAtomic(gamesFile, previousGames, fs);
            await commitAtomic(restore, gamesFile, fs);
          }
        } catch {
          // The digest mismatch still makes the pair detectable and refusable.
        }
      }
      throw error;
    }
  });
}

// What: hashes the exact ordered PGN batch as a JSON array.
// Why: report and PGN files are separate writes, so readers need proof that they belong together.
// Removed: a crash or hand edit could silently pair one report with different games.
export function digestGames(pgns: readonly string[]): string {
  return createHash('sha256').update(JSON.stringify(pgns), 'utf8').digest('hex');
}

export async function saveReport(root: string, sessionId: string, text: string): Promise<void> {
  await exclusive(root, async () => {
    const dir = sessionDir(root, sessionId);
    await stat(path.join(dir, 'meta.json'));
    await writeAtomic(path.join(dir, 'report.json'), text);
  });
}

